import { DatabaseSync, type SQLInputValue } from 'node:sqlite';
import { mkdirSync } from 'node:fs';
import { dirname } from 'node:path';

/** Opens the SQLite database shared by the server and worker processes, creating the schema if needed. */
export function openDatabase(path: string = process.env.DATABASE_PATH ?? 'data/jobs.db'): DatabaseSync {
  if (path !== ':memory:') mkdirSync(dirname(path), { recursive: true });
  const db = new DatabaseSync(path);
  // busy_timeout first: switching to WAL takes a brief exclusive lock, and the server and worker
  // open the same database at once, so the loser must wait rather than fail.
  db.exec('PRAGMA busy_timeout = 5000; PRAGMA journal_mode = WAL;');
  db.exec(`
    CREATE TABLE IF NOT EXISTS jobs (
      seq INTEGER PRIMARY KEY AUTOINCREMENT,
      id TEXT NOT NULL UNIQUE,
      status TEXT NOT NULL,
      input TEXT NOT NULL,
      steps INTEGER NOT NULL,
      fail_attempts INTEGER NOT NULL,
      attempts INTEGER NOT NULL DEFAULT 0,
      progress_completed INTEGER NOT NULL DEFAULT 0,
      result_output TEXT,
      error TEXT,
      idempotency_key TEXT UNIQUE,
      available_at INTEGER NOT NULL DEFAULT 0,
      created_at TEXT NOT NULL,
      updated_at TEXT NOT NULL
    );
    CREATE INDEX IF NOT EXISTS jobs_queue ON jobs (status, available_at, seq);
    CREATE TABLE IF NOT EXISTS worker_heartbeat (
      id INTEGER PRIMARY KEY CHECK (id = 1),
      pid INTEGER NOT NULL,
      seen_at INTEGER NOT NULL
    );
  `);
  return db;
}

/** Runs a query and returns all rows. */
export function all<T>(db: DatabaseSync, sql: string, ...params: SQLInputValue[]): T[] {
  return db.prepare(sql).all(...params) as unknown as T[];
}

/** Runs a query and returns the first row, or undefined. */
export function get<T>(db: DatabaseSync, sql: string, ...params: SQLInputValue[]): T | undefined {
  return db.prepare(sql).get(...params) as unknown as T | undefined;
}

/** Runs a statement and returns the number of rows changed. */
export function run(db: DatabaseSync, sql: string, ...params: SQLInputValue[]): number {
  return Number(db.prepare(sql).run(...params).changes);
}
/** Job model shared by the server and the worker. */

export const STEP_MS = 100;
/** Delay before a failed attempt is retried. Must be between 250 ms and 2 s. */
export const RETRY_DELAY_MS = 500;
/** Total attempts allowed, including the first. */
export const MAX_ATTEMPTS = 3;
export const MAX_INPUT_LENGTH = 1000;
export const MAX_STEPS = 20;
export const MAX_FAIL_ATTEMPTS = 5;
export const DEFAULT_STEPS = 5;
export const DEFAULT_FAIL_ATTEMPTS = 0;

export type JobStatus = 'queued' | 'running' | 'completed' | 'failed';

/** Row shape of the `jobs` table. */
export interface JobRow {
  seq: number;
  id: string;
  status: JobStatus;
  input: string;
  steps: number;
  fail_attempts: number;
  attempts: number;
  progress_completed: number;
  result_output: string | null;
  error: string | null;
  idempotency_key: string | null;
  available_at: number;
  created_at: string;
  updated_at: string;
}

/** Job as returned by the HTTP API. */
export interface JobJson {
  id: string;
  status: JobStatus;
  input: string;
  steps: number;
  failAttempts: number;
  attempts: number;
  progress: { completed: number; total: number };
  result: { output: string } | null;
  error: string | null;
  createdAt: string;
  updatedAt: string;
}

export function toJob(row: JobRow): JobJson {
  return {
    id: row.id,
    status: row.status,
    input: row.input,
    steps: row.steps,
    failAttempts: row.fail_attempts,
    attempts: row.attempts,
    progress: { completed: row.progress_completed, total: row.steps },
    result: row.status === 'completed' && row.result_output !== null ? { output: row.result_output } : null,
    error: row.status === 'failed' ? row.error : null,
    createdAt: row.created_at,
    updatedAt: row.updated_at,
  };
}

export interface FieldError {
  field: string;
  message: string;
}

export interface NewJob {
  input: string;
  steps: number;
  failAttempts: number;
}

const ALLOWED_FIELDS = new Set(['input', 'steps', 'failAttempts']);

/** Validates a parsed request body. Returns the job parameters with defaults applied, or the field errors. */
export function validateNewJob(body: unknown): { ok: true; value: NewJob } | { ok: false; fields: FieldError[] } {
  if (typeof body !== 'object' || body === null || Array.isArray(body)) {
    return { ok: false, fields: [{ field: 'body', message: 'Request body must be a JSON object.' }] };
  }
  const obj = body as Record<string, unknown>;
  const fields: FieldError[] = [];

  for (const key of Object.keys(obj)) {
    if (!ALLOWED_FIELDS.has(key)) fields.push({ field: key, message: `Unknown field "${key}".` });
  }

  const input = obj.input;
  if (input === undefined) {
    fields.push({ field: 'input', message: 'input is required.' });
  } else if (typeof input !== 'string') {
    fields.push({ field: 'input', message: 'input must be a string.' });
  } else if (input.length < 1 || input.length > MAX_INPUT_LENGTH) {
    fields.push({ field: 'input', message: `input must be 1 to ${MAX_INPUT_LENGTH} characters.` });
  } else if (input.trim().length === 0) {
    fields.push({ field: 'input', message: 'input must not be only whitespace.' });
  }

  const steps = obj.steps === undefined ? DEFAULT_STEPS : obj.steps;
  if (!isIntegerInRange(steps, 1, MAX_STEPS)) {
    fields.push({ field: 'steps', message: `steps must be an integer from 1 to ${MAX_STEPS}.` });
  }

  const failAttempts = obj.failAttempts === undefined ? DEFAULT_FAIL_ATTEMPTS : obj.failAttempts;
  if (!isIntegerInRange(failAttempts, 0, MAX_FAIL_ATTEMPTS)) {
    fields.push({ field: 'failAttempts', message: `failAttempts must be an integer from 0 to ${MAX_FAIL_ATTEMPTS}.` });
  }

  if (fields.length > 0) return { ok: false, fields };
  return { ok: true, value: { input: input as string, steps: steps as number, failAttempts: failAttempts as number } };
}

function isIntegerInRange(v: unknown, min: number, max: number): v is number {
  return typeof v === 'number' && Number.isInteger(v) && v >= min && v <= max;
}
import { createServer, type IncomingMessage, type ServerResponse } from 'node:http';
import { randomUUID } from 'node:crypto';
import { readFileSync } from 'node:fs';
import type { DatabaseSync } from 'node:sqlite';
import { all, get, openDatabase, run } from './db.ts';
import { toJob, validateNewJob, type FieldError, type JobRow } from './jobs.ts';

/** A worker heartbeat older than this means the worker is down. */
const WORKER_STALE_MS = 3_000;
const MAX_BODY_BYTES = 64 * 1024;
const IDEMPOTENCY_KEY_RE = /^[A-Za-z0-9_-]{1,128}$/;
const JOB_PATH_RE = /^\/api\/jobs\/([^/]+)$/;

const db: DatabaseSync = openDatabase();
const uiHtml = readFileSync(new URL('../ui/index.html', import.meta.url), 'utf8');

function sendJson(res: ServerResponse, status: number, body: unknown): void {
  res.writeHead(status, { 'content-type': 'application/json; charset=utf-8' });
  res.end(JSON.stringify(body));
}

function sendError(res: ServerResponse, status: number, code: string, message: string, fields?: FieldError[]): void {
  const error: { code: string; message: string; fields?: FieldError[] } = { code, message };
  if (fields) error.fields = fields;
  sendJson(res, status, { error });
}

function isJsonContentType(value: string | undefined): boolean {
  if (!value) return false;
  return value.split(';')[0]!.trim().toLowerCase() === 'application/json';
}

type BodyResult = { ok: true; text: string } | { ok: false };

/** Reads the whole request body, up to MAX_BODY_BYTES. */
function readBody(req: IncomingMessage): Promise<BodyResult> {
  return new Promise((resolve, reject) => {
    const chunks: Buffer[] = [];
    let size = 0;
    let tooLarge = false;
    req.on('data', (chunk: Buffer) => {
      size += chunk.length;
      if (size > MAX_BODY_BYTES) tooLarge = true;
      else chunks.push(chunk);
    });
    req.on('end', () => resolve(tooLarge ? { ok: false } : { ok: true, text: Buffer.concat(chunks).toString('utf8') }));
    req.on('error', reject);
  });
}

function findByKey(key: string): JobRow | undefined {
  return get<JobRow>(db, 'SELECT * FROM jobs WHERE idempotency_key = ?', key);
}

async function handleCreateJob(req: IncomingMessage, res: ServerResponse): Promise<void> {
  const keyHeader = req.headers['idempotency-key'];
  const idempotencyKey = Array.isArray(keyHeader) ? keyHeader.join(', ') : keyHeader;
  const bodyResult = await readBody(req);

  const fields: FieldError[] = [];
  if (idempotencyKey !== undefined && !IDEMPOTENCY_KEY_RE.test(idempotencyKey)) {
    fields.push({ field: 'Idempotency-Key', message: 'Idempotency-Key must match ^[A-Za-z0-9_-]{1,128}$.' });
  }
  if (!isJsonContentType(req.headers['content-type'])) {
    fields.push({ field: 'body', message: 'Content-Type must be application/json.' });
  } else if (!bodyResult.ok) {
    fields.push({ field: 'body', message: `Request body must be at most ${MAX_BODY_BYTES} bytes.` });
  } else {
    let parsed: unknown;
    let parseOk = true;
    try {
      parsed = JSON.parse(bodyResult.text);
    } catch {
      parseOk = false;
    }
    if (!parseOk) {
      fields.push({ field: 'body', message: 'Request body is not valid JSON.' });
    } else {
      const validated = validateNewJob(parsed);
      if (!validated.ok) {
        fields.push(...validated.fields);
      } else if (fields.length === 0) {
        const payload = validated.value;
        if (idempotencyKey !== undefined) {
          const existing = findByKey(idempotencyKey);
          if (existing) {
            if (existing.input === payload.input && existing.steps === payload.steps && existing.fail_attempts === payload.failAttempts) {
              sendJson(res, 200, toJob(existing));
            } else {
              sendError(res, 409, 'idempotency_conflict', 'This Idempotency-Key was already used with a different payload.');
            }
            return;
          }
        }
        const now = new Date().toISOString();
        const id = randomUUID();
        run(
          db,
          `INSERT INTO jobs (id, status, input, steps, fail_attempts, attempts, progress_completed, idempotency_key, available_at, created_at, updated_at)
           VALUES (?, 'queued', ?, ?, ?, 0, 0, ?, 0, ?, ?)`,
          id,
          payload.input,
          payload.steps,
          payload.failAttempts,
          idempotencyKey ?? null,
          now,
          now,
        );
        const row = get<JobRow>(db, 'SELECT * FROM jobs WHERE id = ?', id)!;
        sendJson(res, 201, toJob(row));
        return;
      }
    }
  }
  sendError(res, 400, 'invalid_request', 'The request is invalid.', fields);
}

function handleListJobs(res: ServerResponse): void {
  const rows = all<JobRow>(db, 'SELECT * FROM jobs ORDER BY seq DESC');
  sendJson(res, 200, { jobs: rows.map(toJob) });
}

function handleGetJob(res: ServerResponse, id: string): void {
  const row = get<JobRow>(db, 'SELECT * FROM jobs WHERE id = ?', id);
  if (!row) {
    sendError(res, 404, 'not_found', 'No job with that id.');
    return;
  }
  sendJson(res, 200, toJob(row));
}

function handleHealth(res: ServerResponse): void {
  const hb = get<{ seen_at: number }>(db, 'SELECT seen_at FROM worker_heartbeat WHERE id = 1');
  const up = hb !== undefined && Date.now() - hb.seen_at < WORKER_STALE_MS;
  sendJson(res, 200, { status: 'ok', worker: up ? 'up' : 'down' });
}

async function route(req: IncomingMessage, res: ServerResponse): Promise<void> {
  const { pathname } = new URL(req.url ?? '/', 'http://localhost');
  const method = req.method ?? 'GET';
  const notAllowed = () => sendError(res, 405, 'method_not_allowed', `${method} is not allowed on ${pathname}.`);

  if (pathname === '/') {
    if (method !== 'GET') return notAllowed();
    res.writeHead(200, { 'content-type': 'text/html; charset=utf-8' });
    res.end(uiHtml);
    return;
  }
  if (pathname === '/health') {
    if (method !== 'GET') return notAllowed();
    return handleHealth(res);
  }
  if (pathname === '/api/jobs') {
    if (method === 'GET') return handleListJobs(res);
    if (method === 'POST') return handleCreateJob(req, res);
    return notAllowed();
  }
  const match = JOB_PATH_RE.exec(pathname);
  if (match) {
    if (method !== 'GET') return notAllowed();
    let id: string;
    try {
      id = decodeURIComponent(match[1]!);
    } catch {
      return sendError(res, 404, 'not_found', 'No job with that id.');
    }
    return handleGetJob(res, id);
  }
  sendError(res, 404, 'not_found', `No route for ${pathname}.`);
}

const port = Number(process.env.PORT ?? 3000);
const server = createServer((req, res) => {
  route(req, res).catch((e: unknown) => {
    console.error('request failed:', e);
    if (!res.headersSent) sendError(res, 500, 'internal_error', 'Internal server error.');
    else res.end();
  });
});

server.listen(port, () => console.log(`server listening on ${port}`));

function shutdown(): void {
  server.close(() => {
    db.close();
    process.exit(0);
  });
  server.closeAllConnections();
}

process.on('SIGTERM', shutdown);
process.on('SIGINT', shutdown);
import { setTimeout as sleep } from 'node:timers/promises';
import type { DatabaseSync } from 'node:sqlite';
import { get, openDatabase, run } from './db.ts';
import { MAX_ATTEMPTS, RETRY_DELAY_MS, STEP_MS, type JobRow } from './jobs.ts';

const HEARTBEAT_MS = 1_000;
const IDLE_POLL_MS = 200;

const db: DatabaseSync = openDatabase();
let stopping = false;

function heartbeat(): void {
  run(
    db,
    `INSERT INTO worker_heartbeat (id, pid, seen_at) VALUES (1, ?, ?)
     ON CONFLICT (id) DO UPDATE SET pid = excluded.pid, seen_at = excluded.seen_at`,
    process.pid,
    Date.now(),
  );
}

/** Jobs left `running` belonged to a worker that died. Put them back in the queue. */
function recoverInterrupted(): number {
  return run(db, `UPDATE jobs SET status = 'queued', progress_completed = 0, available_at = 0, updated_at = ? WHERE status = 'running'`, new Date().toISOString());
}

function nextQueued(): JobRow | undefined {
  return get<JobRow>(
    db,
    `SELECT * FROM jobs WHERE status = 'queued' AND available_at <= ? ORDER BY seq ASC LIMIT 1`,
    Date.now(),
  );
}

function requeue(id: string, availableAt: number): void {
  run(db, `UPDATE jobs SET status = 'queued', progress_completed = 0, available_at = ?, updated_at = ? WHERE id = ?`, availableAt, new Date().toISOString(), id);
}

function fail(id: string, error: string): void {
  run(db, `UPDATE jobs SET status = 'failed', error = ?, result_output = NULL, updated_at = ? WHERE id = ?`, error, new Date().toISOString(), id);
}

function complete(id: string, output: string, steps: number): void {
  run(
    db,
    `UPDATE jobs SET status = 'completed', result_output = ?, progress_completed = ?, error = NULL, updated_at = ? WHERE id = ?`,
    output,
    steps,
    new Date().toISOString(),
    id,
  );
}

/** Runs one attempt of a job. The job is already marked running and its attempts counter incremented. */
async function runAttempt(job: JobRow, attempt: number): Promise<void> {
  if (attempt <= job.fail_attempts) {
    // Simulated transient failure, before any progress.
    if (attempt >= MAX_ATTEMPTS) fail(job.id, 'transient failure');
    else requeue(job.id, Date.now() + RETRY_DELAY_MS);
    return;
  }

  for (let step = 1; step <= job.steps; step++) {
    await sleep(STEP_MS);
    if (stopping) {
      // Shutting down mid-attempt: leave the job queued so it is picked up again on restart.
      requeue(job.id, 0);
      return;
    }
    run(db, `UPDATE jobs SET progress_completed = ?, updated_at = ? WHERE id = ?`, step, new Date().toISOString(), job.id);
  }
  complete(job.id, job.input.toUpperCase(), job.steps);
}

async function processNext(): Promise<boolean> {
  const job = nextQueued();
  if (!job) return false;
  // Claim the job. The status check guards against any other writer changing it first.
  const claimed = run(
    db,
    `UPDATE jobs SET status = 'running', attempts = attempts + 1, progress_completed = 0, updated_at = ? WHERE id = ? AND status = 'queued'`,
    new Date().toISOString(),
    job.id,
  );
  if (claimed === 0) return true;
  const attempt = job.attempts + 1;
  await runAttempt(job, attempt);
  return true;
}

function shutdown(): void {
  stopping = true;
}

process.on('SIGTERM', shutdown);
process.on('SIGINT', shutdown);

const recovered = recoverInterrupted();
if (recovered > 0) console.log(`re-queued ${recovered} interrupted job(s)`);
heartbeat();
const heartbeatTimer = setInterval(heartbeat, HEARTBEAT_MS);
console.log('worker started');

while (!stopping) {
  const busy = await processNext();
  if (!busy) await sleep(IDLE_POLL_MS);
}

clearInterval(heartbeatTimer);
run(db, 'DELETE FROM worker_heartbeat WHERE id = 1');
db.close();
console.log('worker stopped');
process.exit(0);
