<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>Job tracker</title>
  <style>
    body { font-family: system-ui, sans-serif; margin: 2rem auto; max-width: 48rem; padding: 0 1rem; color: #1a1a1a; }
    form { display: grid; grid-template-columns: 1fr; gap: 0.5rem; padding: 1rem; border: 1px solid #ccc; border-radius: 6px; }
    label { display: grid; gap: 0.25rem; font-size: 0.9rem; }
    input { font: inherit; padding: 0.4rem; }
    .row { display: flex; gap: 1rem; }
    .row label { flex: 1; }
    button { font: inherit; padding: 0.5rem 1rem; align-self: start; cursor: pointer; }
    [role="alert"] { color: #b00020; margin: 0.5rem 0; white-space: pre-line; }
    [role="alert"]:empty { display: none; }
    ul { list-style: none; padding: 0; }
    li[data-testid="job-item"] { border: 1px solid #ddd; border-radius: 6px; padding: 0.6rem 0.8rem; margin: 0.5rem 0; }
    .meta { display: flex; gap: 1rem; font-size: 0.9rem; }
    .result { font-family: ui-monospace, monospace; word-break: break-all; margin-top: 0.3rem; }
    .result.failed { color: #b00020; }
  </style>
</head>
<body>
  <h1>Job tracker</h1>

  <form data-testid="job-form" id="job-form" novalidate>
    <label>Input
      <input data-testid="job-input" name="input" type="text" maxlength="1000" required>
    </label>
    <div class="row">
      <label>Steps
        <input data-testid="job-steps" name="steps" type="text" inputmode="numeric" placeholder="5">
      </label>
      <label>Fail attempts
        <input data-testid="job-fail-attempts" name="failAttempts" type="text" inputmode="numeric" placeholder="0">
      </label>
    </div>
    <div>
      <button data-testid="job-submit" type="submit">Submit job</button>
    </div>
    <div data-testid="form-error" role="alert"></div>
  </form>

  <h2>Jobs</h2>
  <ul data-testid="job-list" id="job-list"></ul>

  <script>
    (function () {
      var form = document.getElementById('job-form');
      var formError = document.querySelector('[data-testid="form-error"]');
      var submitButton = document.querySelector('[data-testid="job-submit"]');
      var list = document.getElementById('job-list');
      var lastJson = null;

      // Blank fields are omitted so the server applies its defaults. Numeric text is sent as a number;
      // anything else is sent as typed, so the server's validation reports it.
      function fieldValue(raw) {
        var trimmed = raw.trim();
        if (trimmed === '') return undefined;
        var n = Number(trimmed);
        return trimmed !== '' && isFinite(n) ? n : raw;
      }

      function showError(message) {
        formError.textContent = message;
      }

      function describeRejection(body, status) {
        var error = body && body.error;
        if (!error) return 'Request failed with status ' + status + '.';
        var lines = [error.message || 'The request was rejected.'];
        if (Array.isArray(error.fields)) {
          error.fields.forEach(function (f) {
            lines.push(f.field + ': ' + f.message);
          });
        }
        return lines.join('\n');
      }

      form.addEventListener('submit', function (event) {
        event.preventDefault();
        var body = {};
        var input = form.elements.namedItem('input').value;
        body.input = input;
        var steps = fieldValue(form.elements.namedItem('steps').value);
        if (steps !== undefined) body.steps = steps;
        var failAttempts = fieldValue(form.elements.namedItem('failAttempts').value);
        if (failAttempts !== undefined) body.failAttempts = failAttempts;

        submitButton.disabled = true;
        showError('');
        fetch('/api/jobs', {
          method: 'POST',
          headers: { 'content-type': 'application/json' },
          body: JSON.stringify(body)
        }).then(function (res) {
          return res.json().catch(function () { return null; }).then(function (json) {
            if (res.status === 201 || res.status === 200) {
              form.reset();
              form.elements.namedItem('input').focus();
              refresh();
            } else {
              showError(describeRejection(json, res.status));
            }
          });
        }).catch(function (err) {
          showError('Could not reach the server: ' + err.message);
        }).finally(function () {
          submitButton.disabled = false;
        });
      });

      function render(jobs) {
        var fragment = document.createDocumentFragment();
        jobs.forEach(function (job) {
          var li = document.createElement('li');
          li.setAttribute('data-testid', 'job-item');
          li.setAttribute('data-job-id', job.id);

          var meta = document.createElement('div');
          meta.className = 'meta';
          var status = document.createElement('span');
          status.setAttribute('data-testid', 'job-status');
          status.textContent = job.status;
          var progress = document.createElement('span');
          progress.setAttribute('data-testid', 'job-progress');
          progress.textContent = job.progress.completed + '/' + job.progress.total;
          var input = document.createElement('span');
          input.textContent = JSON.stringify(job.input);
          meta.appendChild(status);
          meta.appendChild(progress);
          meta.appendChild(input);

          var result = document.createElement('div');
          result.setAttribute('data-testid', 'job-result');
          result.className = 'result' + (job.status === 'failed' ? ' failed' : '');
          if (job.status === 'completed' && job.result) result.textContent = job.result.output;
          else if (job.status === 'failed' && job.error) result.textContent = job.error;

          li.appendChild(meta);
          li.appendChild(result);
          fragment.appendChild(li);
        });
        list.replaceChildren(fragment);
      }

      function refresh() {
        return fetch('/api/jobs').then(function (res) {
          return res.ok ? res.json() : null;
        }).then(function (body) {
          if (!body || !Array.isArray(body.jobs)) return;
          var json = JSON.stringify(body.jobs);
          if (json === lastJson) return;
          lastJson = json;
          render(body.jobs);
        }).catch(function () {
          // Keep the last list on screen; the next poll retries.
        });
      }

      refresh();
      setInterval(refresh, 1000);
    })();
  </script>
</body>
</html>

